begin;
do $$
declare org uuid:='ec42a08a-0f59-4b7b-a48e-b2faacf9eaf1';brand uuid:='88718f61-2915-42ef-b62f-5e6e2fe5b3eb';other_brand uuid:='88a73473-5dc7-471c-b484-fe247cf0f660';
 c jsonb;v jsonb;p jsonb;o jsonb;r jsonb;payload jsonb;req uuid:=gen_random_uuid();denied boolean;plan uuid;actor uuid;limited uuid;
begin
 perform set_config('request.jwt.claims','{"sub":"b6ee4db2-0f37-4b3e-a3ee-fa804ec5e6cd","role":"authenticated"}',true);
 actor:=marketing_private.actor();
 payload:='{"name":"Disposable Creator Management QA","locations":["QA Ipoh","qa ipoh","QA Penang"],"categories":["QA Food","qa food"],"profiles":[{"platform":"instagram","profile_url":"https://instagram.com/feedx_management_qa_one/"},{"platform":"tiktok","profile_url":"https://www.tiktok.com/@feedx_management_qa_two"}]}';
 c:=marketing_creator_command(req,org,null,'save_creator',null,0,payload);
 assert marketing_creator_command(req,org,null,'save_creator',null,0,payload)=c;
 assert not exists(select 1 from marketing_creator_brands where creator_id=(c->>'id')::uuid);
 assert jsonb_array_length(c->'locations')=2 and jsonb_array_length(c->'categories')=1;
 assert (select count(*) from marketing_creator_accounts where creator_id=(c->>'id')::uuid)=2;
 denied:=false;begin perform marketing_creator_command(gen_random_uuid(),org,null,'save_creator',null,0,payload);exception when unique_violation then denied:=true;end;assert denied,'Atomic duplicate prevention failed';
 -- Reproduce pre-normalization spelling/spacing without changing any business row.
 update marketing_creators set locations=array[' qa   ipoh ','QA Penang'],location=' qa   ipoh ' where id=(c->>'id')::uuid;
 select to_jsonb(x) into o from marketing_creator_options x where organization_id=org and kind='location' and normalized='qa ipoh';
 denied:=false;begin perform marketing_creator_command(gen_random_uuid(),org,null,'option_rename',(o->>'id')::uuid,(o->>'revision')::int,'{"kind":"location","name":"QA Kuala Lumpur"}');exception when others then denied:=true;end;assert denied,'Used-option impact confirmation absent';
 o:=marketing_creator_command(gen_random_uuid(),org,null,'option_rename',(o->>'id')::uuid,(o->>'revision')::int,'{"kind":"location","name":"QA Kuala Lumpur","confirm_impact":true}');
 assert (select 'QA Kuala Lumpur'=any(locations) from marketing_creators where id=(c->>'id')::uuid);
 o:=marketing_creator_command(gen_random_uuid(),org,null,'option_delete',(o->>'id')::uuid,(o->>'revision')::int,'{"kind":"location","confirm_impact":true}');
 select to_jsonb(t) into c from marketing_creators t where id=(c->>'id')::uuid;
 c:=marketing_creator_command(gen_random_uuid(),org,null,'save_creator',(c->>'id')::uuid,(c->>'revision')::int,c||'{"notes":"Safe edit preserves archived options"}');
 assert (select archived from marketing_creator_options where id=(o->>'id')::uuid);
 assert 'QA Kuala Lumpur' in(select jsonb_array_elements_text(c->'locations'));
 payload:=jsonb_build_object('title','Disposable three-platform collaboration','creator_id',c->>'id','status','in_progress','cash_cost',10,'in_kind_cost',5,'currency','MYR','cost_state','estimated','deliverables','[{"title":"IG Reel","platform":"instagram","content_type":"video","status":"pending"},{"title":"TikTok Video","platform":"tiktok","content_type":"video","status":"pending"},{"title":"XHS Picture","platform":"xhs","content_type":"image","status":"pending"}]'::jsonb);
 v:=marketing_creator_command(gen_random_uuid(),org,brand,'save_collaboration',null,0,payload);
 assert (select count(*) from marketing_creator_brands where creator_id=(c->>'id')::uuid)=1;
 denied:=false;begin perform marketing_creator_command(gen_random_uuid(),org,brand,'save_collaboration',(v->>'id')::uuid,(v->>'revision')::int,payload||'{"status":"published"}');exception when others then denied:=true;end;assert denied,'Published without evidence accepted';
 select (x->>'id')::uuid into plan from jsonb_array_elements(v->'deliverables')x where x->>'platform'='instagram';
 p:=marketing_creator_command(gen_random_uuid(),org,brand,'save_post',null,0,jsonb_build_object('url','https://www.instagram.com/p/FeedxManagementQA/','creator_id',c->>'id','confirm_link',true,'content_type','video','confirm_published',true));
 p:=marketing_creator_command(gen_random_uuid(),org,brand,'link_post',(p->>'id')::uuid,(p->>'revision')::int,jsonb_build_object('collaboration_id',v->>'id','deliverable_id',plan,'content_type','video','confirm_link',true));
 assert p->>'collaboration_id'=v->>'id';assert (select count(*) from marketing_creator_posts where post_key='FeedxManagementQA')=1;
 payload:=v||'{"status":"published"}';
 v:=marketing_creator_command(gen_random_uuid(),org,brand,'save_collaboration',(v->>'id')::uuid,(v->>'revision')::int,payload);
 assert (select count(*) from marketing_creator_deliverables where collaboration_id=(v->>'id')::uuid and status='pending')=3,'Partial publishing completed other plans';
 denied:=false;begin perform marketing_creator_command(gen_random_uuid(),org,brand,'save_post',(p->>'id')::uuid,(p->>'revision')::int,p||jsonb_build_object('url',p->>'canonical_url','collaboration_id','','deliverable_id',''));exception when others then denied:=true;end;assert denied,'Removed last Published evidence';
 v:=marketing_creator_command(gen_random_uuid(),org,brand,'save_collaboration',(v->>'id')::uuid,(v->>'revision')::int,v||'{"status":"completed"}');
 assert (select count(*) from marketing_creator_deliverables where collaboration_id=(v->>'id')::uuid and status='pending')=3;
 -- Optional Creator uses the existing Brand-scoped collaboration, not a second authority.
 r:=marketing_creator_command(gen_random_uuid(),org,brand,'save_collaboration',null,0,'{"title":"Disposable unassigned collaboration","status":"planned","deliverables":[]}');assert r->>'creator_id' is null;
 -- Isolated role fixture: same identity is visible, other-brand details stay private, shared edit denied.
 perform marketing_creator_command(gen_random_uuid(),org,other_brand,'save_collaboration',null,0,jsonb_build_object('title','Disposable other-brand collaboration','creator_id',c->>'id','status','planned','deliverables','[]'::jsonb));
 insert into roles(name) values('Disposable Creator Management scope') returning id into limited;
 insert into role_permissions(role_id,permission_id) select limited,id from permissions where code in('marketing_workspace.access','marketing_creators.view','marketing_creators.manage');
 insert into marketing_role_scopes values(org,limited,false);insert into marketing_role_brands values(org,limited,other_brand);
 update employees set role_id=limited where id=actor;
 update platform_member_brand_scopes set all_brands=false where organization_id=org and employee_id=actor;
 delete from platform_member_brands where organization_id=org and employee_id=actor;
 insert into platform_member_brands values(org,actor,other_brand);
 r:=marketing_creators_read(org,other_brand);
 assert not exists(select 1 from jsonb_array_elements(r->'collaborations') x where x->>'id'=v->>'id');
 assert not (select (x->>'editable')::boolean from jsonb_array_elements(r->'creators') x where x->>'id'=c->>'id');
 denied:=false;begin perform marketing_creator_command(gen_random_uuid(),org,null,'save_creator',(c->>'id')::uuid,(c->>'revision')::int,c);exception when insufficient_privilege then denied:=true;end;assert denied;
 denied:=false;begin perform marketing_creators_read(org,brand);exception when insufficient_privilege then denied:=true;end;assert denied;
 assert not has_table_privilege('authenticated','marketing_creator_options','select');
 assert not has_function_privilege('authenticated','marketing_private.creator_bind(uuid,uuid,uuid)','execute');
 perform set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000099","role":"authenticated"}',true);
 denied:=false;begin perform marketing_creators_read(org,null);exception when insufficient_privilege then denied:=true;end;assert denied;
end;$$;
select 'PASS: name-only Creator, atomic profiles, independent normalized options, rename/archive preservation, explicit Brand links, partial publication, canonical Post reuse, closure, retries and scope denial. All fixtures rolled back.' verification;
rollback;
